        if (st.alias) |alias| {
            _ = &alias;
            _ = try self.export_props.append(p.allocator, .{ .key = Expr.init(E.String, .{ .data = alias.original_name }, stmt.loc), .value = Expr.initIdentifier(deduped.namespace_ref, stmt.loc) });
        } else {
            _ = try self.export_star_props.append(p.allocator, .{ .kind = .spread, .value = Expr.initIdentifier(deduped.namespace_ref, stmt.loc) });
        }
        return;
},
.s_import => |st| {
_ = try self.deduplicatedImport(p, st.import_record_index, st.namespace_ref, st.items, st.star_name_loc, st.default_name, stmt.loc);
        return;
},
else => {
new_stmt = stmt;
},
}
        _ = try self.stmts.append(p.allocator, new_stmt);
}

pub fn deduplicatedImport(self: *ConvertESMExportsForHmr, p: anytype, import_record_index: u32, namespace_ref: Ref, items: []js_ast.ClauseItem, star_name_loc: ?logger.Loc, default_name: ?js_ast.LocRef, loc: logger.Loc) DeduplicatedImportResult!void {
        const ir = (&p.import_records.items[@as(usize, @intCast(import_record_index))]);
        const gop = try self.imports_seen.getOrPut(p.allocator, ir.path.text);
        if (gop.found_existing) {
            ir.flags.is_unused = true;
            const stmt = self.stmts.items[@as(usize, @intCast(gop.value_ptr.stmt_index))].data.s_import;
            p.import_records.items[@as(usize, @intCast(stmt.import_record_index))].flags.is_unused = false;
            if ((items.len > 0)) {
                if ((stmt.items.len == 0)) {
                    stmt.items = items;
                } else {
                    const slices = .{ stmt.items, items };
                    stmt.items = try std.mem.concat(p.allocator, js_ast.ClauseItem, (&slices));
                }
            }
            if (namespace_ref.isValid()) {
                if ((!stmt.namespace_ref.isValid())) {
                    stmt.namespace_ref = namespace_ref;
                    return DeduplicatedImportResult{ .namespace_ref = namespace_ref, .import_record_index = stmt.import_record_index };
                } else {
                    const symbol = (&p.symbols.items[@as(usize, @intCast(namespace_ref.innerIndex()))]);
                    symbol.use_count_estimate = 0;
                    symbol.link = stmt.namespace_ref;
                    if (@hasField(@typeInfo(@TypeOf(p)).pointer.child, "symbol_uses")) {
                        _ = p.symbol_uses.swapRemove(namespace_ref);
                    }
                }
            }
            if ((stmt.star_name_loc == null)) {
                if (star_name_loc) |stl| {
                    _ = &stl;
                    stmt.star_name_loc = stl;
                }
            }
            if ((stmt.default_name == null)) {
                if (default_name) |dn| {
                    _ = &dn;
                    stmt.default_name = dn;
                }
            }
            return DeduplicatedImportResult{ .namespace_ref = stmt.namespace_ref, .import_record_index = stmt.import_record_index };
        }
        _ = try self.stmts.append(p.allocator, Stmt.alloc(S.Import, .{ .import_record_index = import_record_index, .is_single_line = true, .default_name = default_name, .items = items, .namespace_ref = namespace_ref, .star_name_loc = star_name_loc }, loc));
        gop.value_ptr.* = ImportRef{ .stmt_index = @intCast((self.stmts.items.len - 1)) };
        return DeduplicatedImportResult{ .namespace_ref = namespace_ref, .import_record_index = import_record_index };
}

pub fn visitBindingToExport(self: *ConvertESMExportsForHmr, p: anytype, binding: Binding) !void {
        switch (binding.data) {
.b_missing => {

},
.b_identifier => |id| {
_ = try self.visitRefToExport(p, id.ref, null, binding.loc, false);
},
.b_array => |array| {
for (array.items) |item| {
            _ = &item;
            _ = try self.visitBindingToExport(p, item.binding);
        }
},
.b_object => |object| {
for (cp_iter_slice(object.properties)) |item| {
            _ = &item;
            _ = try self.visitBindingToExport(p, (if (@typeInfo(@TypeOf(item)) == .@"enum") @intFromEnum(item) else item.value));
        }
},
}
}

pub fn visitRefToExport(self: *ConvertESMExportsForHmr, p: anytype, r: Ref, export_symbol_name: ?[]const u8, loc: logger.Loc, is_live_binding_source: bool) !void {
        const symbol = p.symbols.items[@as(usize, @intCast(r.inner_index))];
        const id = (if ((symbol.kind == .@"import")) Expr.init(E.ImportIdentifier, .{ .ref = r }, loc) else Expr.initIdentifier(r, loc));
        if (((is_live_binding_source or ((symbol.kind == .@"import") and (!self.is_in_node_modules))) or symbol.has_been_assigned_to)) {
            const key = Expr.init(E.String, .{ .data = ((export_symbol_name) orelse (symbol.original_name)) }, loc);
            const arg1 = p.generateTempRef(symbol.original_name);
            _ = try self.last_part.declared_symbols.append(p.allocator, .{ .ref = arg1, .is_top_level = true });
            _ = try self.last_part.symbol_uses.putNoClobber(p.allocator, arg1, .{ .count_estimate = 1 });
            _ = try p.current_scope.generated.append(p.allocator, arg1);
            const ret_stmts = .{ Stmt.alloc(S.Return, .{ .value = id }, loc) };
            _ = try self.export_props.append(p.allocator, .{ .kind = .get, .key = key, .value = Expr.init(E.Function, .{ .func = .{ .body = .{ .stmts = try p.allocator.dupe(Stmt, (&ret_stmts)), .loc = loc } } }, loc) });
        } else {
            _ = try self.export_props.append(p.allocator, .{ .key = Expr.init(E.String, .{ .data = ((export_symbol_name) orelse (symbol.original_name)) }, loc), .value = id });
        }
}

pub fn finalize(self: *ConvertESMExportsForHmr, p: anytype, all_parts: []js_ast.Part) !void {
        if ((self.export_star_props.items.len > 0)) {
            if ((self.export_props.items.len == 0)) {
                self.export_props = self.export_star_props;
            } else {
                const export_star_len = self.export_star_props.items.len;
                _ = try self.export_props.ensureUnusedCapacity(p.allocator, export_star_len);
                const len = self.export_props.items.len;
                self.export_props.items.len = (self.export_props.items.len + export_star_len);
                _ = bun.copy(G.Property, self.export_props.items[export_star_len..], self.export_props.items[0..len]);
                _ = @memcpy(self.export_props.items[0..export_star_len], self.export_star_props.items);
            }
        }
        if ((self.export_props.items.len > 0)) {
            const obj = Expr.init(E.Object, .{ .properties = G.Property.List.moveFromList((&self.export_props)) }, logger.Loc.Empty);
            _ = try self.stmts.append(p.allocator, Stmt.alloc(S.SExpr, .{ .value = Expr.assign(Expr.init(E.Dot, .{ .target = Expr.initIdentifier(p.hmr_api_ref, logger.Loc.Empty), .name = "exports", .name_loc = logger.Loc.Empty }, logger.Loc.Empty), obj) }, logger.Loc.Empty));
            _ = try self.last_part.symbol_uses.put(p.allocator, p.module_ref, .{ .count_estimate = 1 });
            _ = try self.last_part.declared_symbols.append(p.allocator, .{ .ref = p.module_ref, .is_top_level = true });
        }
        if ((p.options.features.react_fast_refresh and p.react_refresh.register_used)) {
            _ = try self.stmts.append(p.allocator, Stmt.alloc(S.SExpr, .{ .value = Expr.init(E.Call, .{ .target = Expr.init(E.Dot, .{ .target = Expr.initIdentifier(p.hmr_api_ref, .Empty), .name = "reactRefreshAccept", .name_loc = .Empty }, .Empty), .args = .empty }, .Empty) }, .Empty));
        }
        for (cp_mut_slice(&all_parts[0..(all_parts.len - 1)])) |*part| {
            _ = &part;
            _ = try self.last_part.declared_symbols.appendList(p.allocator, (part.*).declared_symbols);
            _ = try self.last_part.import_record_indices.appendSlice(p.allocator, (part.*).import_record_indices.slice());
            const sym_keys = (part.*).symbol_uses.keys();
            const sym_values = (part.*).symbol_uses.values();
            var i: usize = 0;
            _ = &i;
            while ((i < sym_keys.len)) : (i = (i + 1)) {
                const k = sym_keys[@as(usize, @intCast(i))];
                const v = sym_values[@as(usize, @intCast(i))];
                const gop = try self.last_part.symbol_uses.getOrPut(p.allocator, k);
                if ((!gop.found_existing)) {
                    gop.value_ptr.* = v;
                } else {
                    gop.value_ptr.count_estimate = (gop.value_ptr.count_estimate + v.count_estimate);
                }
            }
            (part.*).stmts = empty_stmts[0..0];
            (part.*).declared_symbols.entries.len = 0;
            (part.*).tag = .dead_due_to_inlining;
            _ = (part.*).dependencies.clearRetainingCapacity();
            _ = try (part.*).dependencies.append(p.allocator, .{ .part_index = @intCast((all_parts.len - 1)), .source_index = p.source.index });
        }
        _ = try self.last_part.import_record_indices.appendSlice(p.allocator, p.import_records_for_current_part.items);
        _ = try self.last_part.declared_symbols.appendList(p.allocator, p.declared_symbols);
        self.last_part.stmts = self.stmts.items;
        self.last_part.tag = .none;
}
const logger = bun.logger;
const js_ast = bun.ast;
const B = js_ast.B;
const Binding = js_ast.Binding;
const E = js_ast.E;
const Expr = js_ast.Expr;
const LocRef = js_ast.LocRef;
const S = js_ast.S;
const Stmt = js_ast.Stmt;
const G = js_ast.G;
const Decl = G.Decl;
const Property = G.Property;
const js_parser = bun.js_parser;
const ReactRefresh = js_parser.ReactRefresh;
const Ref = js_parser.Ref;
const options = js_parser.options;
const List = std.ArrayListUnmanaged;
const empty_stmts: [0]Stmt = &.{};
const empty_clause_items: [0]js_ast.ClauseItem = &.{};
